/*
 * Workspace Kit 0.4.1（https://workspace-kit.vercel.app/kit）
 * globals.css の `@import "tailwindcss";` のすぐ後に `@import "./workspace-kit.css";` と書いて読み込む。
 * テーマの元：awesome-design-skills（Copyright (c) 2026 Bergside, MIT License。許諾文の全文は https://opensource.org/license/mit ）
 */

/* ======== 色・文字・余白・角丸・影・動き・押せる大きさ ======== */
/*
 * Workspace Kit トークン（基準テーマ：グラファイト）
 *
 * 画面の色・文字・余白・角丸・影・動き・押せる大きさを、ここ1か所の CSS 変数で決める。
 * 部品は必ずこの変数を通して色を使う（色コードを部品に直接書かない）。
 *
 * - 明るさ：何も指定しなければ端末の設定に従う。<html data-theme="light|dark"> で固定できる
 * - 密度：<html data-density="compact"> で一覧の行が詰まる（指で触る端末では詰めすぎない）
 * - 押せる大きさ：画面幅ではなく「指かマウスか」(pointer) で決める。マウス 36px／指 44px
 * - ブランド色を変えたいときは --accent 系の4つだけ差し替える
 */

:root {
  /* 面の色（奥 → 手前） */
  --wk-canvas: #f7f7f5;      /* 画面の地 */
  --wk-sidebar: #efeeea;     /* サイドバー・アイコン列 */
  --wk-surface: #ffffff;     /* カード・パネル・シート */
  --wk-surface-2: #f1f0ec;   /* ホバー・弱い塗り */
  --wk-line: #e2e0da;        /* 区切り線・枠 */

  /* 文字 */
  --wk-fg: #1d1c1a;
  --wk-fg-2: #55534e;        /* 補足の文 */
  --wk-fg-3: #6b6964;        /* ラベル・日付（白地で 4.5:1 以上） */

  /* ブランド（差し替えるのはこの4つ） */
  --wk-accent: #2563eb;
  --wk-on-accent: #ffffff;
  --wk-accent-soft: #e7eefc;
  --wk-accent-text: #1d4fc4;

  /* 状態の色（ブランド色とは別に固定） */
  --wk-ok: #18794e;      --wk-ok-soft: #e3f3ea;
  --wk-warn: #8a5200;    --wk-warn-soft: #fbf0dc;
  --wk-danger: #b42323;  --wk-danger-soft: #fbe6e6;  --wk-on-danger: #ffffff;

  /* 重なり */
  --wk-scrim: rgb(20 20 18 / 0.32);
  --wk-shadow-sm: 0 1px 2px rgb(20 20 18 / 0.08);
  --wk-shadow: 0 12px 32px rgb(20 20 18 / 0.14), 0 2px 6px rgb(20 20 18 / 0.08);
  --wk-glass: color-mix(in oklab, var(--wk-surface) 72%, transparent);
  --wk-glass-line: color-mix(in oklab, var(--wk-fg) 8%, transparent);
  --wk-glass-hi: color-mix(in oklab, white 60%, transparent); /* ガラスの上端に光が当たる細い線 */

  /* 角丸（入れ子は「親の角丸 − 余白」） */
  --wk-r-sm: 6px;
  --wk-r-md: 10px;
  --wk-r-lg: 14px;
  --wk-r-pill: 999px;

  /* 文字 */
  --wk-font: var(--wk-font-jp, "IBM Plex Sans JP"), "Hiragino Sans", "Yu Gothic UI", "Meiryo", "Noto Sans JP", system-ui, sans-serif;
  --wk-font-head: var(--wk-font); /* 見出し（テーマによっては飾り文字・明朝になる） */
  --wk-text-xs: 12px;   /* これより小さくしない */
  --wk-text-sm: 13px;
  --wk-text-md: 15px;   /* 本文 */
  --wk-text-input: 16px; /* 入力欄（iPhone の自動ズームを防ぐ） */
  --wk-text-lg: 18px;
  --wk-text-xl: 24px;
  --wk-text-2xl: 28px;  /* 画面の見出しより大きい物（見本サイトの題など） */
  --wk-text-3xl: 34px;

  /* 動き（時間と曲線。速い・普通・ゆっくりの3段と、出る・消える・バネの曲線） */
  --wk-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --wk-ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --wk-ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);
  --wk-dur-press: 120ms;   /* 押し縮み */
  --wk-dur-fast: 160ms;    /* 色・ホバー */
  --wk-dur-base: 240ms;    /* 出し入れ */
  --wk-dur-sheet: 420ms;   /* シート・引き出し */
  --wk-dur-exit: 120ms;    /* メニュー・ダイアログが消えるとき（出るときより速く） */
  /* 押し縮みと出現の倍率（動きを減らす設定では全部 1 になり、大きさは変わらない） */
  --wk-press: 0.97;        /* ボタン・チップ・切り替え */
  --wk-press-round: 0.95;  /* 小さな丸いボタン（右下の主ボタン・送る・チェック） */
  --wk-press-card: 0.985;  /* カード・一覧の大きな面 */
  --wk-hold: 0.96;         /* 長押しの最中（離すと操作シートが開く） */
  --wk-pop: 0.97;          /* メニュー・確認ダイアログが出るときの最初の大きさ */

  /* 押せる大きさ・行の高さ（マウス） */
  --wk-hit: 36px;
  --wk-row: 48px;

  /* 骨格の寸法 */
  --wk-sidebar-w: 240px;
  --wk-rail-w: 72px;
  --wk-tabbar-h: 62px;
  --wk-tabbar-gap: 10px;    /* 下タブと画面下の間 */
  --wk-safe-b: env(safe-area-inset-bottom, 0px);
  /* 下タブがあるとき、本文の下に空ける余白 */
  --wk-tabbar-space: calc(var(--wk-tabbar-h) + var(--wk-tabbar-gap) * 2 + var(--wk-safe-b) + 24px);

  color-scheme: light;
}

/* 指で触る端末：押せる大きさを 44px に */
@media (pointer: coarse) {
  :root { --wk-hit: 44px; --wk-row: 56px; }
}
:root[data-density="compact"] { --wk-row: 40px; }
@media (pointer: coarse) {
  :root[data-density="compact"] { --wk-row: 48px; }
}

/* ダーク：端末の設定（明示のライト指定が無いとき） */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --wk-canvas: #161615; --wk-sidebar: #111110; --wk-surface: #1f1f1d; --wk-surface-2: #2a2a27; --wk-line: #34332f;
    --wk-fg: #ecebe7; --wk-fg-2: #b6b4ae; --wk-fg-3: #95938d;
    --wk-accent: #5b8cff; --wk-on-accent: #0b1530; --wk-accent-soft: #1c2a4d; --wk-accent-text: #9db9ff;
    --wk-ok: #4cc38a; --wk-ok-soft: #16301f; --wk-warn: #e5a83b; --wk-warn-soft: #33270f; --wk-danger: #ff7a7a; --wk-danger-soft: #3a1717; --wk-on-danger: #2a0b0b;
    --wk-scrim: rgb(0 0 0 / 0.55);
    --wk-shadow-sm: 0 1px 2px rgb(0 0 0 / 0.4);
    --wk-shadow: 0 16px 40px rgb(0 0 0 / 0.5), 0 2px 6px rgb(0 0 0 / 0.4);
    --wk-glass-line: color-mix(in oklab, var(--wk-fg) 12%, transparent);
    --wk-glass-hi: color-mix(in oklab, white 9%, transparent);
    color-scheme: dark;
  }
}
/* ダーク：明示の指定 */
:root[data-theme="dark"] {
  --wk-canvas: #161615; --wk-sidebar: #111110; --wk-surface: #1f1f1d; --wk-surface-2: #2a2a27; --wk-line: #34332f;
  --wk-fg: #ecebe7; --wk-fg-2: #b6b4ae; --wk-fg-3: #95938d;
  --wk-accent: #5b8cff; --wk-on-accent: #0b1530; --wk-accent-soft: #1c2a4d; --wk-accent-text: #9db9ff;
  --wk-ok: #4cc38a; --wk-ok-soft: #16301f; --wk-warn: #e5a83b; --wk-warn-soft: #33270f; --wk-danger: #ff7a7a; --wk-danger-soft: #3a1717; --wk-on-danger: #2a0b0b;
  --wk-scrim: rgb(0 0 0 / 0.55);
  --wk-shadow-sm: 0 1px 2px rgb(0 0 0 / 0.4);
  --wk-shadow: 0 16px 40px rgb(0 0 0 / 0.5), 0 2px 6px rgb(0 0 0 / 0.4);
  --wk-glass-line: color-mix(in oklab, var(--wk-fg) 12%, transparent);
  --wk-glass-hi: color-mix(in oklab, white 9%, transparent);
  color-scheme: dark;
}

/* 動きを減らす設定：移動と拡大縮小は止め、色と透明度の変化は短く残す（パッと切り替わって何が起きたか分からなくならないように）。
   シートは横すべりの代わりにフェードで出入りする（base.css） */
@media (prefers-reduced-motion: reduce) {
  :root {
    --wk-dur-press: 1ms; --wk-dur-base: var(--wk-dur-fast); --wk-dur-sheet: var(--wk-dur-fast);
    --wk-press: 1; --wk-press-round: 1; --wk-press-card: 1; --wk-hold: 1; --wk-pop: 1;
  }
}

/* ======== Tailwind のクラス名との対応 ======== */
/*
 * Workspace Kit トークンを Tailwind v4 のクラス名で使えるようにする対応表。
 * 例：bg-canvas / bg-surface / text-fg-2 / border-line / bg-accent / text-on-accent / rounded-md / h-hit
 * globals.css で `@import "tailwindcss";` の後に読み込む。
 */
@theme inline {
  --color-canvas: var(--wk-canvas);
  --color-sidebar: var(--wk-sidebar);
  --color-surface: var(--wk-surface);
  --color-surface-2: var(--wk-surface-2);
  --color-line: var(--wk-line);
  --color-fg: var(--wk-fg);
  --color-fg-2: var(--wk-fg-2);
  --color-fg-3: var(--wk-fg-3);
  --color-accent: var(--wk-accent);
  --color-on-accent: var(--wk-on-accent);
  --color-accent-soft: var(--wk-accent-soft);
  --color-accent-text: var(--wk-accent-text);
  --color-ok: var(--wk-ok);
  --color-ok-soft: var(--wk-ok-soft);
  --color-warn: var(--wk-warn);
  --color-warn-soft: var(--wk-warn-soft);
  --color-danger: var(--wk-danger);
  --color-danger-soft: var(--wk-danger-soft);
  --color-on-danger: var(--wk-on-danger);
  --color-scrim: var(--wk-scrim);

  --radius-sm: var(--wk-r-sm);
  --radius-md: var(--wk-r-md);
  --radius-lg: var(--wk-r-lg);

  --shadow-sm: var(--wk-shadow-sm);
  --shadow-float: var(--wk-shadow);

  --font-sans: var(--wk-font);

  --text-xs: var(--wk-text-xs);
  --text-sm: var(--wk-text-sm);
  --text-base: var(--wk-text-md);
  --text-lg: var(--wk-text-lg);
  --text-xl: var(--wk-text-xl);
  --text-2xl: var(--wk-text-2xl);
  --text-3xl: var(--wk-text-3xl);

  --ease-out: var(--wk-ease-out);
  --ease-in-out: var(--wk-ease-in-out);
  --ease-drawer: var(--wk-ease-drawer);
  /* transition-colors などで時間と曲線を書き忘れても、キットの値になる（Tailwind の既定 150ms・ease-in-out にしない） */
  --default-transition-duration: var(--wk-dur-fast);
  --default-transition-timing-function: var(--wk-ease-out);

  --spacing-hit: var(--wk-hit);
  --spacing-row: var(--wk-row);
  --spacing-sidebar: var(--wk-sidebar-w);
  --spacing-rail: var(--wk-rail-w);

  /* 骨格の切り替え点：768px 未満＝下タブ／768〜1279px＝アイコン列／1280px 以上＝サイドバー */
  --breakpoint-rail: 48rem;
  --breakpoint-side: 80rem;
}

/* ======== テーマ12種（<html data-palette="…"> で切り替え） ======== */
/*
 * Workspace Kit テーマ集：仕上げた12種（packages/themes/convert.mjs が生成。手で書き換えない）
 * 使い方：<html data-palette="テーマの id">。明るさ（data-theme）・密度（data-density）とは別に切り替えられる
 * 元の色・文字・角丸：awesome-design-skills（Copyright (c) 2026 Bergside, MIT License）。名前と日本語対応・コントラスト調整は Workspace Kit
 */
/* グラファイト（Workspace Kit 独自） */
:root[data-palette="graphite"] { --wk-canvas: #f5f7f9; --wk-sidebar: #edeff3; --wk-surface: #fefeff; --wk-surface-2: #eceef1; --wk-line: #dadce0; --wk-fg: #191b1e; --wk-fg-2: #4d5054; --wk-fg-3: #66696e; --wk-accent: #2563eb; --wk-on-accent: #ffffff; --wk-accent-soft: #e4edff; --wk-accent-text: #1f5ce4; --wk-ok-soft: #e2f6e9; --wk-ok: #12764b; --wk-warn-soft: #ffeddc; --wk-warn: #8e5300; --wk-danger-soft: #ffebe8; --wk-danger: #b42223; --wk-on-danger: #ffffff; --wk-font: "IBM Plex Sans", "IBM Plex Sans JP", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-font-head: "IBM Plex Sans", "IBM Plex Sans JP", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-r-sm: 6px; --wk-r-md: 10px; --wk-r-lg: 14px; }
@media (prefers-color-scheme: dark) { :root[data-palette="graphite"]:not([data-theme="light"]) { --wk-canvas: #0e0f12; --wk-sidebar: #0a0b0d; --wk-surface: #18191c; --wk-surface-2: #232427; --wk-line: #2f3033; --wk-fg: #eaebee; --wk-fg-2: #bcbec0; --wk-fg-3: #97989b; --wk-accent: #73a2ff; --wk-on-accent: #081123; --wk-accent-soft: #182a4e; --wk-accent-text: #82adff; --wk-ok-soft: #112d1e; --wk-ok: #76cd9d; --wk-warn-soft: #382006; --wk-warn: #f1a453; --wk-danger-soft: #3f1916; --wk-danger: #ff968b; --wk-on-danger: #22110f; color-scheme: dark; } }
