/* クリニック（Workspace Kit 独自） */
:root[data-palette="clinic"] { --wk-canvas: #f4f8f6; --wk-sidebar: #ecf0ee; --wk-surface: #fdfefe; --wk-surface-2: #ebefed; --wk-line: #d9dedb; --wk-fg: #171c1a; --wk-fg-2: #4c514f; --wk-fg-3: #656a68; --wk-accent: #008464; --wk-on-accent: #ffffff; --wk-accent-soft: #daf4e9; --wk-accent-text: #00785b; --wk-ok-soft: #e2f6e9; --wk-ok: #12764b; --wk-warn-soft: #ffeddc; --wk-warn: #8e5300; --wk-danger-soft: #ffebe8; --wk-danger: #b4221f; --wk-on-danger: #ffffff; --wk-font: "Zen Maru Gothic", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-font-head: "Zen Maru Gothic", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-r-sm: 10px; --wk-r-md: 14px; --wk-r-lg: 20px; }
@media (prefers-color-scheme: dark) { :root[data-palette="clinic"]:not([data-theme="light"]) { --wk-canvas: #0d100f; --wk-sidebar: #090c0b; --wk-surface: #171a19; --wk-surface-2: #222523; --wk-line: #2e3130; --wk-fg: #e9eceb; --wk-fg-2: #bbbebd; --wk-fg-3: #969998; --wk-accent: #52bb98; --wk-on-accent: #02160f; --wk-accent-soft: #0b3327; --wk-accent-text: #5dc4a1; --wk-ok-soft: #112d1e; --wk-ok: #76cd9d; --wk-warn-soft: #382006; --wk-warn: #f1a453; --wk-danger-soft: #3f1916; --wk-danger: #ff9689; --wk-on-danger: #22110e; color-scheme: dark; } }
:root[data-palette="clinic"][data-theme="dark"] { --wk-canvas: #0d100f; --wk-sidebar: #090c0b; --wk-surface: #171a19; --wk-surface-2: #222523; --wk-line: #2e3130; --wk-fg: #e9eceb; --wk-fg-2: #bbbebd; --wk-fg-3: #969998; --wk-accent: #52bb98; --wk-on-accent: #02160f; --wk-accent-soft: #0b3327; --wk-accent-text: #5dc4a1; --wk-ok-soft: #112d1e; --wk-ok: #76cd9d; --wk-warn-soft: #382006; --wk-warn: #f1a453; --wk-danger-soft: #3f1916; --wk-danger: #ff9689; --wk-on-danger: #22110e; color-scheme: dark; }

/* ナイト（Workspace Kit 独自） */
:root[data-palette="night"] { --wk-canvas: #0b0f19; --wk-sidebar: #070b14; --wk-surface: #141924; --wk-surface-2: #1e2430; --wk-line: #2a303d; --wk-fg: #e7ebf3; --wk-fg-2: #babec6; --wk-fg-3: #9498a0; --wk-accent: #5cc8ff; --wk-on-accent: #00141f; --wk-accent-soft: #053043; --wk-accent-text: #5cc8ff; --wk-ok-soft: #072e1d; --wk-ok: #5cd298; --wk-warn-soft: #352200; --wk-warn: #e8ab3f; --wk-danger-soft: #3f1919; --wk-danger: #ff9592; --wk-on-danger: #221010; color-scheme: dark; --wk-font: "IBM Plex Sans", "IBM Plex Sans JP", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-font-head: "IBM Plex Sans", "IBM Plex Sans JP", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-r-sm: 6px; --wk-r-md: 10px; --wk-r-lg: 14px; }
:root[data-palette="night"][data-theme="dark"] { --wk-canvas: #0b0f19; --wk-sidebar: #070b14; --wk-surface: #141924; --wk-surface-2: #1e2430; --wk-line: #2a303d; --wk-fg: #e7ebf3; --wk-fg-2: #babec6; --wk-fg-3: #9498a0; --wk-accent: #5cc8ff; --wk-on-accent: #00141f; --wk-accent-soft: #053043; --wk-accent-text: #5cc8ff; --wk-ok-soft: #072e1d; --wk-ok: #5cd298; --wk-warn-soft: #352200; --wk-warn: #e8ab3f; --wk-danger-soft: #3f1919; --wk-danger: #ff9592; --wk-on-danger: #221010; color-scheme: dark; }

/* スカイ（元：ant ／ awesome-design-skills・MIT） */
:root[data-palette="sky"] { --wk-canvas: #eff8ff; --wk-sidebar: #e4f1fa; --wk-surface: #fdfeff; --wk-surface-2: #e3f0f9; --wk-line: #d0dfe9; --wk-fg: #121c23; --wk-fg-2: #46525a; --wk-fg-3: #5f6b73; --wk-accent: #007bba; --wk-on-accent: #ffffff; --wk-accent-soft: #ddf0ff; --wk-accent-text: #006fa9; --wk-ok-soft: #def8e2; --wk-ok: #007832; --wk-warn-soft: #ffecdf; --wk-warn: #944f00; --wk-danger-soft: #ffebe8; --wk-danger: #bc0011; --wk-on-danger: #ffffff; --wk-font: "Plus Jakarta Sans", "Noto Sans JP", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-font-head: "Plus Jakarta Sans", "Noto Sans JP", "Hiragino Sans", "Yu Gothic UI", "Meiryo", system-ui, sans-serif; --wk-r-sm: 6px; --wk-r-md: 8px; --wk-r-lg: 12px; }
@media (prefers-color-scheme: dark) { :root[data-palette="sky"]:not([data-theme="light"]) { --wk-canvas: #081116; --wk-sidebar: #050c12; --wk-surface: #121b20; --wk-surface-2: #1c252c; --wk-line: #273239; --wk-fg: #e4edf2; --wk-fg-2: #b7bfc5; --wk-fg-3: #92999f; --wk-accent: #46aef3; --wk-on-accent: #011322; --wk-accent-soft: #062e47; --wk-accent-text: #51b7fe; --wk-ok-soft: #0d2e15; --wk-ok: #59d579; --wk-warn-soft: #3c1e03; --wk-warn: #ff9c46; --wk-danger-soft: #3f1916; --wk-danger: #ff968a; --wk-on-danger: #22110e; color-scheme: dark; } }
