/* ======== 土台と骨格 ======== */
/*
 * Workspace Kit の土台と骨格の CSS（tokens.css・tailwind.css の後に読み込む）。
 */

/* ---- 土台 ----
 * @layer base に入れる（入れないと Tailwind の部品の指定 outline-none などより強くなり、部品側で打ち消せない）
 */
@layer base {
  html {
    background: var(--wk-canvas);
    color: var(--wk-fg);
    font-family: var(--wk-font);
    line-height: 1.6;
    -webkit-text-size-adjust: 100%;
    -webkit-font-smoothing: antialiased;
  }
  /* 本文は 15px。html は既定の 16px のまま（rem＝Tailwind の大きさの単位を 16px に保つ。後付けした画面の大きさが変わらず、text-2xl が text-xl より小さくなる逆転も起きない） */
  body { min-height: 100dvh; background: var(--wk-canvas); font-size: var(--wk-text-md); }
  button, [role="button"], a { touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
  button:not(:disabled), [role="button"] { cursor: pointer; }
  input, textarea, select { font-size: var(--wk-text-input); }
  :focus-visible { outline: 2px solid var(--wk-accent); outline-offset: 2px; }
  .num { font-variant-numeric: tabular-nums; }
  h1, h2, h3 { text-wrap: balance; font-family: var(--wk-font-head); }
  /* 日本語は文節で折り返す（「ヒーロ／ー画像」のような切れ方をさせない。対応していないブラウザは今まで通り） */
  :lang(ja) { word-break: auto-phrase; }
}

/* ---- 骨格（3段階）----
 * 767px 以下：下タブ（左の列なし）
 * 768〜1279px：アイコン列 72px
 * 1280px 以上：サイドバー 240px（畳むとアイコン列）
 * 本文はこの幅だけ右へずらす。どの幅でもナビは必ず1つ見える（消える幅を作らない）
 */
:root { --wk-nav-w: 0px; }
@media (min-width: 48rem) { :root { --wk-nav-w: var(--wk-rail-w); } }
@media (min-width: 80rem) {
  :root { --wk-nav-w: var(--wk-sidebar-w); }
  :root[data-sidebar="collapsed"] { --wk-nav-w: var(--wk-rail-w); }
}
/* 幅の切り替えは動かさない（padding や width を動かすと、本文の長い一覧まで毎コマ組み直しになる） */
.wk-content { padding-left: var(--wk-nav-w); }
@media (max-width: 47.99rem) {
  .wk-content { padding-bottom: var(--wk-tabbar-space); }
}

/* サイドバーの文字は「広い・畳んでいない」ときだけ出す */
.wk-nav-label { display: none; }
@media (min-width: 80rem) {
  :root:not([data-sidebar="collapsed"]) .wk-nav-label { display: inline; }
  :root:not([data-sidebar="collapsed"]) .wk-nav-wide { display: flex; }
}
.wk-nav-wide { display: none; }

/* 上に貼り付く見出し（すりガラス） */
/* -webkit- 付きは書かない。両方書くとビルド（lightningcss）が -webkit- 付きだけを残し、Chrome ではぼかしが消える。
   接頭辞なしだけを書けば、Safari 用の -webkit- 付きはビルドが足す */
.wk-glass-top {
  background: color-mix(in oklab, var(--wk-canvas) 82%, transparent);
  backdrop-filter: blur(14px) saturate(1.3);
}
@media (prefers-reduced-transparency: reduce) {
  .wk-glass-top { background: var(--wk-canvas); backdrop-filter: none; }
  .wk-glass-bar { background: var(--wk-surface); backdrop-filter: none; }
}

/* 読み込みの骨：150ms 待ってから出す（速いときにチラつかせない） */
@keyframes wk-skeleton-in { from { opacity: 0 } to { opacity: 1 } }
@keyframes wk-skeleton-pulse { 50% { opacity: 0.55 } }
.wk-skeleton {
  background: var(--wk-surface-2);
  border-radius: var(--wk-r-sm);
  opacity: 0;
  animation: wk-skeleton-in 1ms 150ms forwards, wk-skeleton-pulse 1.4s 150ms ease-in-out infinite;
}

@keyframes wk-spin { to { transform: rotate(360deg) } }
.wk-spin { animation: wk-spin 0.7s linear infinite; }
@media (prefers-reduced-motion: reduce) {
  .wk-spin { animation-duration: 2s; }
  .wk-skeleton { animation: wk-skeleton-in 1ms 150ms forwards; }
}

/* AI の返事が届いている間のしるし（文字の後ろの棒・考え中の点） */
@keyframes wk-blink { 50% { opacity: 0 } }
.wk-caret {
  display: inline-block; width: 7px; height: 1.05em; margin-left: 2px; vertical-align: -2px;
  background: var(--wk-accent); animation: wk-blink 1s steps(2) infinite;
}
@keyframes wk-dots { 0% { content: "" } 25% { content: "・" } 50% { content: "・・" } 75% { content: "・・・" } }
.wk-dots::after { content: "・・・"; display: inline-block; width: 3em; animation: wk-dots 1.2s steps(1) infinite; }
@media (prefers-reduced-motion: reduce) {
  .wk-caret, .wk-dots::after { animation: none; }
}

/* お知らせ（sonner）の高さ。下タブが出る幅（767px 以下）では下タブの上に出す。
   sonner のスマホ用の指定は 600px 以下しか効かないので、ここで 767px まで上書きする。
   右下の主ボタン（.wk-fab）がある画面では、その上に出す（主ボタンを隠して押せなくしない） */
@media (max-width: 47.99rem) {
  [data-sonner-toaster][data-y-position="bottom"] {
    bottom: calc(var(--wk-tabbar-h) + var(--wk-tabbar-gap) * 2 + var(--wk-safe-b)) !important;
  }
  :root:has(.wk-fab) [data-sonner-toaster][data-y-position="bottom"] {
    bottom: calc(var(--wk-tabbar-h) + var(--wk-tabbar-gap) + var(--wk-safe-b) + 14px + 3.5rem + 10px) !important;
  }
}

/* 一覧の行の「…」（.wk-row-more）。マウスの端末では、行に乗せた・選んだ・キーボードで中に入ったときだけ出す（全行に並ぶとざわつく）。
   指の端末は常に出す（乗せる操作が無いため） */
@media (pointer: fine) {
  [data-row] .wk-row-more { opacity: 0; transition: opacity var(--wk-dur-fast) var(--wk-ease-out); }
  [data-row]:is(:hover, :focus-within, [data-on]) .wk-row-more,
  .wk-row-more[data-popup-open] { opacity: 1; }
  /* 矢印キーで選ぶ行はすぐ出す（1日に何十回もする操作に動きを付けない） */
  [data-row][data-on] .wk-row-more { transition: none; }
}

/* シート（vaul）の時間と曲線をキットの値にそろえる。vaul は 0.5 秒で固定され、動きを減らす設定も見ない */
[data-vaul-drawer], [data-vaul-overlay] {
  animation-duration: var(--wk-dur-sheet) !important;
  animation-timing-function: var(--wk-ease-drawer) !important;
}
/* 閉じるときは速く（出るときより短く。続けて次のシートを開くときにもたつかない） */
[data-vaul-drawer][data-state="closed"], [data-vaul-overlay][data-state="closed"] { animation-duration: var(--wk-dur-base) !important; }
/* 指を離して元の位置へ戻る動き。vaul は自分の CSS を後から差し込み、離したときは style に直接 0.5 秒を書くので !important で上書きする */
[data-vaul-drawer] { transition-duration: var(--wk-dur-sheet) !important; transition-timing-function: var(--wk-ease-drawer) !important; }
/* PC の右から浮いた引き出しでは、vaul が右に足す延長部分（引きすぎたときの隙間埋め）を出さない。
   画面の端との 12px のすき間に白い帯が見えてしまう */
[data-vaul-drawer][data-vaul-drawer-direction="right"]::after { content: none !important; } /* vaul の指定と強さが同じで、vaul は後から差し込まれるので !important が要る */
@keyframes wk-fade-in { from { opacity: 0 } }
@keyframes wk-fade-out { to { opacity: 0 } }
@media (prefers-reduced-motion: reduce) {
  /* 動きを減らす設定：すべらせず、その場でフェードして出入りする */
  [data-vaul-drawer][data-state="open"] { animation-name: wk-fade-in !important; }
  [data-vaul-drawer][data-state="closed"] { animation-name: wk-fade-out !important; }
  [data-vaul-drawer], [data-vaul-overlay] { animation-timing-function: var(--wk-ease-out) !important; }
}

/* お知らせ（sonner）の出入りもキットの曲線と時間にする（既定は 0.4 秒・ease） */
[data-sonner-toast] {
  transition-duration: var(--wk-dur-base) !important;
  transition-timing-function: var(--wk-ease-out) !important;
}
